// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    address constant OWNER = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

    function setUp() public { c = new EBU(); }

    function testFuzz_property(address to, uint256 amount) public {
        vm.assume(to != address(0));
        amount = bound(amount, 0, type(uint128).max / 1e18);
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint256[] memory vs = new uint256[](1);
        vs[0] = amount;
        vm.prank(OWNER);
        (bool ok, bytes memory ret) = address(c).call(
            abi.encodeWithSelector(c.transfer.selector, tos, vs)
        );
        assertTrue(ok && abi.decode(ret, (bool)) == true);
    }
}
